query Search($q: String!, $take: Int!) {
  customers(options: {
    filter: { emailAddress: { contains: $q }, firstName: { contains: $q }, lastName: { contains: $q } },
    filterOperator: OR, take: $take, sort: { lastName: ASC }
  }) {
    totalItems
    items { id createdAt updatedAt title firstName lastName emailAddress phoneNumber customFields }
  }
}
